<?php require dirname(__DIR__).'/app/bootstrap.php';$me=require_login(true);$error='';
if(!empty($me['mfa_required'])&&empty($me['mfa_enabled'])){header('Location: '.path('admin/mfa.php'));exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_verify();$current=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');$u=query_one('SELECT password_hash FROM users WHERE id=?',[(int)$me['id']]);
 if(!$u||!password_verify($current,$u['password_hash']))$error='Current password is incorrect.';
 elseif(strlen($new)<14||$new!==$confirm||hash_equals($current,$new))$error='New passwords must match, differ from the old password, and contain at least 14 characters.';
 else{$newVersion=(int)($me['session_version']??1)+1;db()->prepare('UPDATE users SET password_hash=?,force_password_change=0,password_changed_at='.sql_now().',session_version=? WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),$newVersion,(int)$me['id']]);$_SESSION['user']['session_version']=$newVersion;$_SESSION['user']['force_password_change']=false;audit_log('password_changed','user',(int)$me['id']);flash('Password changed. Other sessions were revoked.');header('Location: '.path('admin/index.php'));exit;}
}
?><!doctype html><html lang="rw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Change Password · AFRIVOX NEWS</title><link rel="stylesheet" href="<?=e(path('assets/style.css'))?>"><link rel="stylesheet" href="<?=e(path('assets/admin.css'))?>"></head><body class="login-page"><main class="login-panel"><div class="overline">SECURITY REQUIRED</div><h1>Hindura <em>password.</em></h1><p>Konti nshya igomba guhindura initial password mbere yo gukomeza.</p><?php if($error):?><div class="form-error"><?=e($error)?></div><?php endif;?><form method="post" class="public-form"><?=csrf_field()?><label>CURRENT PASSWORD<input type="password" name="current_password" autocomplete="current-password" required></label><label>NEW PASSWORD<input type="password" name="new_password" minlength="14" autocomplete="new-password" required></label><label>CONFIRM NEW PASSWORD<input type="password" name="confirm_password" minlength="14" autocomplete="new-password" required></label><button>CHANGE PASSWORD →</button></form></main></body></html>
